package org.freecad.mobilelab;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** ASCII modelspace LINE, CIRCLE, ARC and straight LWPOLYLINE. Units must be declared. */
final class DxfImporter {
 static final class Pair{final int code;final String value;Pair(int c,String v){code=c;value=v;}}
 static double number(List<Pair> a,int code,double fallback)throws IOException{for(Pair p:a)if(p.code==code){try{double d=Double.parseDouble(p.value);if(Double.isFinite(d))return d;}catch(Exception ignored){}throw new IOException("Invalid DXF number");}return fallback;}
 static int read(File source)throws Exception{
  if(source.length()>16*1024*1024)throw new IOException("DXF exceeds 16 MiB");ArrayList<Pair> pairs=new ArrayList<>();try(BufferedReader r=new BufferedReader(new InputStreamReader(new FileInputStream(source),StandardCharsets.UTF_8))){String key;while((key=r.readLine())!=null){String value=r.readLine();if(value==null||key.length()>32||value.length()>1024||pairs.size()>=200000)throw new IOException("Invalid or oversized DXF records");pairs.add(new Pair(Integer.parseInt(key.trim()),value.trim()));}}
  int units=-1;for(int i=0;i+1<pairs.size();i++)if(pairs.get(i).code==9&&pairs.get(i).value.equals("$INSUNITS"))units=Integer.parseInt(pairs.get(i+1).value);double unit=units==1?25.4:units==2?304.8:units==4?1:units==5?10:units==6?1000:Double.NaN;if(!Double.isFinite(unit))throw new IOException("DXF needs declared inch/foot/mm/cm/m $INSUNITS; unitless drawings are ambiguous");ArrayList<Double> values=new ArrayList<>();ArrayList<Integer> kinds=new ArrayList<>();boolean entities=false;
  for(int i=0;i<pairs.size();){Pair start=pairs.get(i);if(start.code==0&&start.value.equals("SECTION")&&i+1<pairs.size()&&pairs.get(i+1).code==2){entities=pairs.get(i+1).value.equals("ENTITIES");i+=2;continue;}if(start.code==0&&start.value.equals("ENDSEC")){entities=false;i++;continue;}if(!entities||start.code!=0){i++;continue;}int end=i+1;while(end<pairs.size()&&pairs.get(end).code!=0)end++;List<Pair> a=pairs.subList(i+1,end);i=end;if(number(a,67,0)!=0)continue;String type=start.value;if(!Arrays.asList("LINE","CIRCLE","ARC","LWPOLYLINE").contains(type))throw new IOException("Unsupported DXF entity: "+type+". Export LINE/CIRCLE/ARC or straight LWPOLYLINE geometry.");if(number(a,210,0)!=0||number(a,220,0)!=0||number(a,230,1)!=1||number(a,39,0)!=0)throw new IOException("DXF extrusion axes/thickness are unsupported");double x=number(a,10,0)*unit,y=number(a,20,0)*unit,z=number(a,30,0)*unit;
   if(type.equals("LINE"))add(kinds,values,0,x,y,z,number(a,11,0)*unit,number(a,21,0)*unit,number(a,31,0)*unit);
   if(type.equals("CIRCLE"))add(kinds,values,1,x,y,z,number(a,40,0)*unit);
   if(type.equals("ARC"))add(kinds,values,2,x,y,z,number(a,40,0)*unit,number(a,50,0),number(a,51,0));
   if(type.equals("LWPOLYLINE")){ArrayList<double[]> pts=new ArrayList<>();double px=0,py=0;boolean haveX=false,haveY=false;z=number(a,38,0)*unit;for(Pair p:a){if(p.code==42&&Double.parseDouble(p.value)!=0)throw new IOException("DXF bulged polylines require conversion to ARC entities");if(p.code==10){if(haveX){if(!haveY)throw new IOException("DXF polyline vertex missing Y");pts.add(new double[]{px,py,z});}px=Double.parseDouble(p.value)*unit;haveX=true;haveY=false;}if(p.code==20){py=Double.parseDouble(p.value)*unit;haveY=true;}}if(haveX&&haveY)pts.add(new double[]{px,py,z});if(pts.size()<2||pts.size()!=number(a,90,pts.size()))throw new IOException("Invalid DXF polyline vertex count");boolean closed=(((int)number(a,70,0))&1)!=0;for(int j=0;j<pts.size()-(closed?0:1);j++){double[] p=pts.get(j),q=pts.get((j+1)%pts.size());add(kinds,values,0,p[0],p[1],p[2],q[0],q[1],q[2]);}}
  }
  if(kinds.isEmpty())throw new IOException("DXF contains no supported modelspace curves");int[] types=new int[kinds.size()];double[] p=new double[values.size()];for(int i=0;i<types.length;i++)types[i]=kinds.get(i);for(int i=0;i<p.length;i++)p[i]=values.get(i);return NativeCad.drawing(p,types);
 }
 static void add(List<Integer> kinds,List<Double> values,int kind,double...p)throws IOException{if(kinds.size()>=2000)throw new IOException("DXF exceeds 2,000 curve segments");for(double v:p)if(!Double.isFinite(v)||Math.abs(v)>1000000)throw new IOException("DXF coordinates exceed +/-1,000,000 mm");kinds.add(kind);for(double v:p)values.add(v);}
}
